%%\ Raincloud plot: nWBV by dementia rating (CDR)
% This script needs the table |T| with one row per subject (the first session, |MR1|), as created in the
% class script. If you run this file on its own, uncomment the next two lines:
raw = readtable("oasis_cross-sectional.csv", "TextType", "string"); %[output:06fc97f7]
T = raw(endsWith(raw.ID, "MR1"), :);

levels3 = [0 0.5 1];                       % CDR 2 is left out: too few participants for a distribution
groups3 = cell(1, 3);
labels3 = strings(1, 3);
for i = 1:3
    g = T.nWBV(T.CDR == levels3(i));
    groups3{i} = g;
    labels3(i) = "CDR " + string(levels3(i)) + newline + "(n=" + string(numel(g)) + ")";
end

cols3 = [0.00 0.45 0.74;       % CDR 0   (blue)
    0.85 0.33 0.10;       % CDR 0.5 (orange)
    0.80 0.15 0.15];      % CDR 1   (red)

figure("Position", [100 100 900 420]) %[output:9ffffe8e]
ax = axes; %[output:9ffffe8e]
raincloud(ax, groups3, labels3, cols3); %[output:9ffffe8e]
xlabel(ax, "Normalized whole-brain volume") %[output:9ffffe8e]

%%\ The raincloud function
% In a script or live script, local functions must be defined at the *end* of the file.
function raincloud(ax, groups, labels, colors, cloudHeight)
% raincloud(ax, groups, labels, colors, cloudHeight)
%   ax          axes to draw into
%   groups      cell array, one numeric vector per group (first group is drawn at the top)
%   labels      string array with one label per group
%   colors      n-by-3 matrix of RGB values, one row per group
%   cloudHeight maximum height of the cloud (default 0.38)
if nargin < 5
    cloudHeight = 0.38;
end
n = numel(groups);
hold(ax, "on")

for i = 1:n
    g = groups{i}(:);
    g = g(~isnan(g));
    y = n - i;                                   % first group at the top
    color = colors(i, :);

    % cloud: smoothed density, drawn above the box, limited to the observed range
    grid = linspace(min(g), max(g), 200);
    dens = ksdensity(g, grid);
    dens = dens(:)' / max(dens) * cloudHeight;
    fill(ax, [grid, fliplr(grid)], ...
        [repmat(y + 0.08, 1, numel(grid)), fliplr(y + 0.08 + dens)], ...
        color, "FaceAlpha", 0.6, "EdgeColor", "none");

    % box: median, quartiles and whiskers (strict 1.5 x IQR criterion), in the middle
    q = quantile(g, [0.25 0.5 0.75]);
    q1 = q(1); med = q(2); q3 = q(3);
    iqrValue = q3 - q1;
    low  = min(g(g >= q1 - 1.5 * iqrValue));
    high = max(g(g <= q3 + 1.5 * iqrValue));
    plot(ax, [low q1], [y y], "k-", "LineWidth", 1)
    plot(ax, [q3 high], [y y], "k-", "LineWidth", 1)
    rectangle(ax, "Position", [q1, y - 0.06, q3 - q1, 0.12], "FaceColor", "w", "EdgeColor", "k")
    plot(ax, [med med], [y - 0.06, y + 0.06], "k-", "LineWidth", 2)

    % rain: every single participant, jittered below the box
    scatter(ax, g, y - 0.12 - 0.2 * rand(size(g)), 8, color, "filled", "MarkerFaceAlpha", 0.6)
end

yticks(ax, 0:n-1)
yticklabels(ax, flip(labels))
ylim(ax, [-0.5, n - 1 + 0.6])
box(ax, "off")
hold(ax, "off")
end

